{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack has too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    return token.lstrip('-').isdigit() and token.count('-') <= 1 and (
        not token.startswith('-') or len(token) > 1) and '-' not in token[1:]


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError('Insufficient number of items in stack')
    values = stack[-count:]
    del stack[-count:]
    return values


def _divide(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError('divide by zero')
    quotient = abs(a) // abs(b)
    stack.append(quotient if (a < 0) == (b < 0) else -quotient)


def _binary(func):
    def apply(stack):
        a, b = _pop(stack, 2)
        stack.append(func(a, b))
    return apply


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend([a, a])


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend([b, a])


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend([a, b, a])


BUILTINS = {
    '+': _binary(lambda a, b: a + b),
    '-': _binary(lambda a, b: a - b),
    '*': _binary(lambda a, b: a * b),
    '/': _divide,
    'dup': _dup,
    'drop': _drop,
    'swap': _swap,
    'over': _over,
}


def evaluate(input_data):
    """Evaluate lines of Forth code and return the resulting stack."""
    # Each user-defined word maps to a list of primitive actions
    # (ints or builtin callables), expanded at definition time.
    words = {name: [func] for name, func in BUILTINS.items()}
    stack = []

    def expand(token):
        if _is_number(token):
            return [int(token)]
        if token in words:
            return words[token]
        raise ValueError('undefined operation')

    tokens = ' '.join(input_data).lower().split()
    index = 0
    while index < len(tokens):
        token = tokens[index]
        index += 1
        if token == ':':
            try:
                end = tokens.index(';', index)
            except ValueError:
                raise ValueError('undefined operation') from None
            if end == index:
                raise ValueError('undefined operation')
            name = tokens[index]
            if _is_number(name):
                raise ValueError('illegal operation')
            body = []
            for part in tokens[index + 1:end]:
                body.extend(expand(part))
            words[name] = body
            index = end + 1
            continue
        for action in expand(token):
            if isinstance(action, int):
                stack.append(action)
            else:
                action(stack)
    return stack
